"33 урока: исследователь, растения, животные, тело человека, воздух, вода, ресурсы, космос, силы, свет, звук, температура, магниты": "33 Lektionen: Forscher, Pflanzen, Tiere, menschlicher Körper, Luft, Wasser, Ressourcen, Weltraum, Kräfte, Licht, Schall, Temperatur, Magnete",
