"Время измеряют секундами, минутами, часами, сутками, неделями, месяцами и годами. Нажимай на карточки.": "Zeit misst man in Sekunden, Minuten, Stunden, Tagen, Wochen, Monaten und Jahren. Drück auf die Karten.",
"Всем живым существам нужен воздух для дыхания. В воздухе есть кислород.": "Alle Lebewesen brauchen Luft zum Atmen. In der Luft ist Sauerstoff.",
