"Если пар из воздуха попадёт на холодный стакан, он превратится в капельки воды.": "Wenn Dampf aus der Luft auf ein kaltes Glas gelangt, verwandelt er sich in Wassertröpfchen.",
"Если пустой стакан вверх дном опустить в воду, вода не зайдёт внутрь. Место занимает воздух.": "Wenn man ein leeres Glas mit der Öffnung nach unten ins Wasser taucht, dringt das Wasser nicht hinein. Den Platz nimmt die Luft ein.",
"Если тело меняет своё место, значит оно движется.": "Wenn ein Körper seinen Ort ändert, bewegt er sich.",
"Железо притягивается магнитом.": "Eisen wird vom Magneten angezogen.",
"Животным вредят браконьеры, вырубка лесов, пожары, загрязнение воды и мусор.": "Tieren schaden Wilderer, Abholzung der Wälder, Brände, Wasserverschmutzung und Müll.",
"Животных делят на группы — классы — по общим признакам. Нажимай на карточки.": "Tiere teilt man nach gemeinsamen Merkmalen in Gruppen ein — Klassen. Drück auf die Karten.",
"Журавли улетают на зиму.": "Kraniche fliegen für den Winter weg.",
"Жёлтая книга": "Gelbes Buch",
"За какое время Земля делает один оборот вокруг Солнца?": "In welcher Zeit macht die Erde eine Umrundung der Sonne?",
"За какое время Земля делает один оборот вокруг своей оси?": "In welcher Zeit macht die Erde eine Umdrehung um ihre eigene Achse?",
"За почвой ухаживают: рыхлят, поливают, удобряют. Тогда растения получают питание.": "Den Boden pflegt man: Man lockert, gießt und düngt ihn. Dann bekommen die Pflanzen Nahrung.",
"Зачем деревья сбрасывают листья осенью?": "Wozu werfen Bäume im Herbst die Blätter ab?",
"Зачем зайцу-беляку зимой белая шёрстка?": "Wozu hat der Schneehase im Winter ein weißes Fell?",
"Зачем кузнечику зелёная окраска?": "Wozu hat die Heuschrecke eine grüne Färbung?",
"Зачем нужны корни?": "Wozu braucht man Wurzeln?",
"Зачем нужны насекомые?": "Wozu braucht man Insekten?",
"Зачем снежному барсу густой мех?": "Wozu hat der Schneeleopard dichtes Fell?",
"Зачем стричь ногти?": "Wozu schneidet man die Nägel?",
"Зачем это животному": "Wozu das für das Tier ist",
"Звук возникает, когда тело дрожит. Нажимай на карточки.": "Schall entsteht, wenn ein Körper zittert. Drück auf die Karten.",
"Звук и слух": "Schall und Gehör",
"Звуки: тихие и громкие": "Töne: leise und laut",
"Здоровье зависит от привычек. Нажимай на карточки.": "Die Gesundheit hängt von den Gewohnheiten ab. Drück auf die Karten.",
"Зелёная тетрадь": "Grünes Heft",
"Земля вращается вокруг своей оси": "Die Erde dreht sich um ihre eigene Achse",
"Земля вращается вокруг своей оси. Один оборот — сутки. Сторона, которую освещает Солнце, — день. Другая сторона — ночь.": "Die Erde dreht sich um ihre eigene Achse. Eine Umdrehung ist ein Tag. Die Seite, die die Sonne beleuchtet, ist Tag. Die andere Seite ist Nacht.",
"Земля летит вокруг Солнца. Один оборот — год. Это около трёхсот шестидесяти пяти суток.": "Die Erde fliegt um die Sonne. Eine Umrundung ist ein Jahr. Das sind etwa dreihundertfünfundsechzig Tage.",
"Земля притягивает все тела. Поэтому яблоко падает вниз, а реки текут вниз.": "Die Erde zieht alle Körper an. Deshalb fällt der Apfel nach unten, und die Flüsse fließen nach unten.",
"Земля то приближается, то удаляется": "Die Erde nähert sich mal und entfernt sich mal",
"Земля — каменная планета.": "Die Erde ist ein Gesteinsplanet.",
"Земля — планета. Она третья от Солнца. На ней есть воздух, вода и жизнь.": "Die Erde ist ein Planet. Sie ist der dritte von der Sonne. Auf ihr gibt es Luft, Wasser und Leben.",
"Земля — третья планета. На ней есть жизнь.": "Die Erde ist der dritte Planet. Auf ihr gibt es Leben.",
"Земля, Солнце и Луна": "Erde, Sonne und Mond",
"Земля, Солнце и Луна связаны между собой. Нажимай на карточки.": "Erde, Sonne und Mond hängen miteinander zusammen. Drück auf die Karten.",
"Земля, Солнце, Луна": "Erde, Sonne, Mond",
"Зимой дерево стоит без листьев и отдыхает": "Im Winter steht der Baum ohne Blätter und ruht sich aus",
"Зимой деревья без листьев отдыхают. Многие травы спрятались под снег. Ель и сосна остаются зелёными.": "Im Winter ruhen die Bäume ohne Blätter. Viele Gräser haben sich unter dem Schnee versteckt. Fichte und Kiefer bleiben grün.",
"Зимой корма мало. Медведь, ёж и барсук проводят зиму в спячке.": "Im Winter gibt es wenig Futter. Bär, Igel und Dachs verbringen den Winter im Winterschlaf.",
"Зимой шерсть зайца-беляка становится белой.": "Im Winter wird das Fell des Schneehasen weiß.",
"Змея — пресмыкающееся.": "Die Schlange ist ein Reptil.",
"Знакомимся с планетами": "Wir lernen die Planeten kennen",
"Знать качества исследователя и правила безопасности": "Die Eigenschaften eines Forschers und die Sicherheitsregeln kennen",
"Знать признаки наблюдения и записывать его условными знаками": "Die Merkmale einer Beobachtung kennen und sie mit Symbolen aufschreiben",
"Знать признаки эксперимента и записывать результаты в таблицу": "Die Merkmale eines Experiments kennen und die Ergebnisse in eine Tabelle schreiben",
"Знать, как беречь осанку, соблюдать личную гигиену и ухаживать за зубами": "Wissen, wie man die Haltung schont, die persönliche Hygiene einhält und die Zähne pflegt",
"Зубам полезны молоко, сыр, овощи. Сладкое вредит. Зубного врача навещай примерно раз в полгода.": "Gut für die Zähne sind Milch, Käse, Gemüse. Süßes schadet. Besuche den Zahnarzt etwa einmal im halben Jahr.",
"Зубы нужно чистить утром и вечером не меньше двух минут.": "Die Zähne muss man morgens und abends mindestens zwei Minuten putzen.",
"Зубы чистят утром и вечером.": "Die Zähne putzt man morgens und abends.",
"Из какой части потом появляются плоды?": "Aus welchem Teil entstehen danach die Früchte?",
"Из облаков идёт дождь или снег": "Aus den Wolken kommt Regen oder Schnee",
