"Исследователь аккуратно обращается с приборами и точно записывает всё, что увидел.": "Ein Forscher geht sorgfältig mit Geräten um und schreibt genau alles auf, was er gesehen hat.",
"Исследователь внимательно смотрит, слушает и замечает мелочи.": "Ein Forscher schaut aufmerksam hin, hört zu und bemerkt Kleinigkeiten.",
"Исследователь всё время спрашивает: «почему?» и «как?». Какое это качество?": "Ein Forscher fragt ständig: „Warum?“ und „Wie?“. Was ist das für eine Eigenschaft?",
"Исследователь замечает мелкие изменения. Какое качество ему нужно?": "Ein Forscher bemerkt kleine Veränderungen. Welche Eigenschaft braucht er?",
"Исследователь замечает мелочи.": "Ein Forscher bemerkt Kleinigkeiten.",
"Исследователь записывает то, что получилось на самом деле, даже если ожидал другого.": "Ein Forscher schreibt auf, was tatsächlich herausgekommen ist, auch wenn er etwas anderes erwartet hat.",
"Исследователь записывает то, что хочет увидеть, а не то, что видит.": "Ein Forscher schreibt auf, was er sehen will, und nicht, was er sieht.",
"Исследователь изучает мир вокруг. Чтобы у него получалось, нужны особые качества. Нажимай на карточки.": "Ein Forscher erforscht die Welt um sich herum. Damit es ihm gelingt, braucht er besondere Eigenschaften. Drück auf die Karten.",
"Исследователь любознательный. Он спрашивает: почему? как? что будет, если…?": "Ein Forscher ist wissbegierig. Er fragt: Warum? Wie? Was geschieht, wenn …?",
"Исследователь сдаётся сразу, если опыт не получился.": "Ein Forscher gibt sofort auf, wenn das Experiment nicht gelungen ist.",
"Исследователь соблюдает правила безопасности.": "Ein Forscher hält die Sicherheitsregeln ein.",
"Исследователь соблюдает правила безопасности. Он не пробует незнакомое на вкус, не трогает горячее и работает вместе со взрослыми.": "Ein Forscher hält die Sicherheitsregeln ein. Er probiert Unbekanntes nicht, fasst Heißes nicht an und arbeitet zusammen mit Erwachsenen.",
"Исследовать силы, вызывающие движение": "Kräfte erforschen, die Bewegung verursachen",
"Исследовать теплопроводность воздуха и его свойство заполнять пространство": "Die Wärmeleitung der Luft und ihre Eigenschaft, den Raum zu füllen, erforschen",
"Исследовать, в каких условиях растут растения": "Erforschen, unter welchen Bedingungen Pflanzen wachsen",
"Исследовать, как вода меняет своё состояние": "Erforschen, wie Wasser seinen Zustand ändert",
"Исследовать, какие тела пропускают свет": "Erforschen, welche Körper Licht durchlassen",
"Источник информации — это то, откуда мы узнаём новое. Чем надёжнее источник, тем вернее знания. Нажимай на карточки.": "Eine Informationsquelle ist das, woher wir Neues erfahren. Je zuverlässiger die Quelle, desto richtiger das Wissen. Drück auf die Karten.",
