"Чтобы быстро записывать, используют условные знаки: солнышко — ясно, облако — облачно, тучка с каплями — дождь, снежинка — снег.": "Um schnell aufzuschreiben, benutzt man Symbole: Sonne — klar, Wolke — bewölkt, Wölkchen mit Tropfen — Regen, Schneeflocke — Schnee.",
"Чтобы выжить, животные приспосабливаются к тому месту, где живут. Нажимай на карточки.": "Um zu überleben, passen sich Tiere an den Ort an, an dem sie leben. Drück auf die Karten.",
"Чтобы кости и мышцы были крепкими, нужно двигаться, заниматься спортом и есть полезную еду.": "Damit Knochen und Muskeln kräftig sind, muss man sich bewegen, Sport treiben und gesund essen.",
"Чтобы проверить, что нужно растению, ставим два одинаковых растения. Одному создаём условие, а другому нет. Потом сравниваем.": "Um zu prüfen, was die Pflanze braucht, stellen wir zwei gleiche Pflanzen auf. Der einen schaffen wir die Bedingung, der anderen nicht. Dann vergleichen wir.",
"Чтобы растение выросло, ему нужны определённые условия. Нажимай на карточки.": "Damit die Pflanze wächst, braucht sie bestimmte Bedingungen. Drück auf die Karten.",
"Чтобы увидеть результат, часто нужно подождать. Растение не вырастет за один день.": "Um das Ergebnis zu sehen, muss man oft warten. Die Pflanze wächst nicht an einem Tag.",
