"Верно ли?<br><b>В воздухе есть кислород, которым мы дышим.</b>": "Stimmt das?<br><b>In der Luft ist Sauerstoff, den wir atmen.</b>",
"Верно ли?<br><b>Воздух бесцветный.</b>": "Stimmt das?<br><b>Luft ist farblos.</b>",
"Верно ли?<br><b>Воздух заполняет всё пространство.</b>": "Stimmt das?<br><b>Luft füllt den ganzen Raum.</b>",
"Верно ли?<br><b>Воздух имеет запах.</b>": "Stimmt das?<br><b>Luft hat einen Geruch.</b>",
"Верно ли?<br><b>Воздух имеет свою форму.</b>": "Stimmt das?<br><b>Luft hat eine eigene Form.</b>",
"Верно ли?<br><b>Воздух — это жидкость.</b>": "Stimmt das?<br><b>Luft ist eine Flüssigkeit.</b>",
"Верно ли?<br><b>Для роста растению нужен свет.</b>": "Stimmt das?<br><b>Die Pflanze braucht Licht zum Wachsen.</b>",
"Верно ли?<br><b>Зубы чистят утром и вечером.</b>": "Stimmt das?<br><b>Die Zähne putzt man morgens und abends.</b>",
"Верно ли?<br><b>Исследователь замечает мелочи.</b>": "Stimmt das?<br><b>Ein Forscher bemerkt Kleinigkeiten.</b>",
"Верно ли?<br><b>Исследователь записывает то, что хочет увидеть, а не то, что видит.</b>": "Stimmt das?<br><b>Ein Forscher schreibt auf, was er sehen will, und nicht, was er sieht.</b>",
"Верно ли?<br><b>Исследователь сдаётся сразу, если опыт не получился.</b>": "Stimmt das?<br><b>Ein Forscher gibt sofort auf, wenn das Experiment nicht gelungen ist.</b>",
"Верно ли?<br><b>Исследователь соблюдает правила безопасности.</b>": "Stimmt das?<br><b>Ein Forscher hält die Sicherheitsregeln ein.</b>",
"Верно ли?<br><b>Конфеты полезны для зубов.</b>": "Stimmt das?<br><b>Bonbons sind gut für die Zähne.</b>",
"Верно ли?<br><b>Молочные зубы можно не чистить, они всё равно выпадут.</b>": "Stimmt das?<br><b>Milchzähne muss man nicht putzen, sie fallen sowieso aus.</b>",
"Верно ли?<br><b>Незнакомые ягоды можно пробовать на вкус.</b>": "Stimmt das?<br><b>Unbekannte Beeren darf man probieren.</b>",
"Верно ли?<br><b>Опыт с растением в темноте покажет, нужен ли ему свет.</b>": "Stimmt das?<br><b>Ein Versuch mit der Pflanze im Dunkeln zeigt, ob sie Licht braucht.</b>",
"Верно ли?<br><b>Осанку нужно беречь с детства.</b>": "Stimmt das?<br><b>Die Haltung muss man von Kindheit an schonen.</b>",
"Верно ли?<br><b>Растению не нужна почва: оно может расти на бумаге без воды.</b>": "Stimmt das?<br><b>Die Pflanze braucht keinen Boden: Sie kann auf Papier ohne Wasser wachsen.</b>",
"Верно ли?<br><b>Растению нужен воздух.</b>": "Stimmt das?<br><b>Die Pflanze braucht Luft.</b>",
"Верно ли?<br><b>Растения могут расти совсем без воды.</b>": "Stimmt das?<br><b>Pflanzen können ganz ohne Wasser wachsen.</b>",
"Верно ли?<br><b>Руки нужно мыть с мылом.</b>": "Stimmt das?<br><b>Die Hände muss man mit Seife waschen.</b>",
"Верно ли?<br><b>Семена прорастают в тепле и во влажной почве.</b>": "Stimmt das?<br><b>Samen keimen in der Wärme und in feuchter Erde.</b>",
"Верно ли?<br><b>Терпение помогает исследователю.</b>": "Stimmt das?<br><b>Geduld hilft dem Forscher.</b>",
"Верно ли?<br><b>Чистить зубы нужно только тогда, когда они болят.</b>": "Stimmt das?<br><b>Die Zähne muss man nur putzen, wenn sie wehtun.</b>",
