"Что выполнит исполнитель?: Алгоритм: если идёт дождь — взять зонт, иначе — шапку. Дождя нет. Что возьмёт исполнитель?": "Was führt der Ausführende aus?: Algorithmus: Wenn es regnet — einen Regenschirm nehmen, sonst — eine Mütze. Es regnet nicht. Was nimmt der Ausführende?",
"Что выполнит исполнитель?: Алгоритм: если идёт дождь — взять зонт, иначе — шапку. Идёт дождь. Что возьмёт исполнитель?": "Was führt der Ausführende aus?: Algorithmus: Wenn es regnet — einen Regenschirm nehmen, sonst — eine Mütze. Es regnet. Was nimmt der Ausführende?",
"Что выполнит исполнитель?: Алгоритм: если светофор красный — стоять, иначе — идти. Светофор зелёный. Что делает исполнитель?": "Was führt der Ausführende aus?: Algorithmus: Wenn die Ampel rot ist — stehen, sonst — gehen. Die Ampel ist grün. Was tut der Ausführende?",
