"Что выполнит исполнитель?: Алгоритм: если число чётное — прибавить 1, иначе — вычесть 1. Число 5. Что получится?": "Was führt der Ausführende aus?: Algorithmus: Wenn die Zahl gerade ist — 1 addieren, sonst — 1 subtrahieren. Die Zahl ist 5. Was kommt heraus?",
